class OrderProcessor {
  constructor(
    private readonly validator: OrderValidator,
    private readonly pricingService: PricingService,
    private readonly paymentService: PaymentService,
    private readonly inventoryService: InventoryService,
    private readonly notificationService: NotificationService
  ) {}

  processOrder(order: Order): void {
    this.validator.validate(order);
    const totalAmount = this.pricingService.calculateTotal(order);
    this.paymentService.charge(order.customerId, totalAmount);
    this.inventoryService.reserveStock(order.items);
    this.notificationService.notifyOrderPlaced(order, totalAmount);
  }
}

